"use client";

import { DESIGN_WIDTH, usePageScale } from "./use-page-scale";

/**
 * The artboards are fixed 1440px canvases. This scales one to fit the
 * window and reserves the scaled height so sections still stack flush.
 */
export function Scaled({
  height,
  children,
}: {
  height: number;
  children: React.ReactNode;
}) {
  const scale = usePageScale();

  return (
    <div
      style={{
        width: "100%",
        height: height * scale,
        display: "flex",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          width: DESIGN_WIDTH,
          height,
          flexShrink: 0,
          transform: `scale(${scale})`,
          transformOrigin: "top center",
        }}
      >
        {children}
      </div>
    </div>
  );
}
